"use strict";

const VIDEO_DATA = "data:video/mp4;base64,";
const FAVICON_DATA = "data:image/png;base64,";

const flavors = Object.freeze([
  {
    id: "zero-sugar",
    eyebrow: "Unleash the beast",
    name: "Monster Energy Zero Sugar",
    shortName: "Zero Sugar",
    description: "O sabor clássico de Monster Energy em uma versão sem açúcar.",
    detail: "Lata preta · detalhes verde neon",
    price: 12.9,
    palette: { background: "#020504", light: "#70f20d", accent: "#8bf21b", accentSoft: "#356b12", particleColors: ["#b6ff42", "#69f50b", "#2e9a10"] },
  },
  {
    id: "ultra-white",
    eyebrow: "Zero sugar · Ultra",
    name: "Monster Ultra White",
    shortName: "Ultra White",
    description: "Perfil cítrico e refrescante com a identidade da linha Monster Ultra.",
    detail: "Lata branca · detalhes prateados",
    price: 12.9,
    palette: { background: "#070a0b", light: "#e6fbff", accent: "#eafcff", accentSoft: "#789aa5", particleColors: ["#ffffff", "#c7eef4", "#8eb8c2"] },
  },
  {
    id: "ultra-fiesta-mango",
    eyebrow: "Zero sugar · Ultra",
    name: "Monster Ultra Fiesta Mango",
    shortName: "Fiesta Mango",
    description: "Perfil tropical de manga, com a identidade leve da linha Monster Ultra.",
    detail: "Lata azul-turquesa · detalhes laranja",
    price: 12.9,
    palette: { background: "#040606", light: "#ff7a18", accent: "#ff9a28", accentSoft: "#087e83", particleColors: ["#ffc257", "#ff7417", "#26c9c7"] },
  },
]);

const formatPrice = (value) => new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" }).format(value);
const params = new URLSearchParams(window.location.search);
const isCheckout = params.get("checkout") === "1";

const favicon = document.querySelector('link[rel~="icon"]');
if (favicon) favicon.href = FAVICON_DATA;

if (isCheckout) initializeCheckout();
else initializeShowcase();

function initializeShowcase() {
  document.body.dataset.view = "home";
  const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)");
  const elements = {
    root: document.documentElement,
    video: document.querySelector("#hero-video"),
    videoStatus: document.querySelector("#video-status"),
    progress: document.querySelector("#video-progress-bar"),
    content: document.querySelector("#product-content"),
    eyebrow: document.querySelector("#flavor-eyebrow"),
    name: document.querySelector("#flavor-name"),
    description: document.querySelector("#flavor-description"),
    detail: document.querySelector("#flavor-detail"),
    price: document.querySelector("#flavor-price"),
    purchaseName: document.querySelector("#purchase-name"),
    buy: document.querySelector("#buy-button"),
    currentIndex: document.querySelector("#current-index"),
    tabs: document.querySelector("#flavor-tabs"),
    particles: document.querySelector("#particles"),
    announcement: document.querySelector("#flavor-announcement"),
  };

  let activeIndex = 0;
  let pointerStartX = null;
  let pointerCurrentX = null;
  let pendingSeekIndex = null;

  function setPalette(flavor) {
    elements.root.style.setProperty("--background", flavor.palette.background);
    elements.root.style.setProperty("--light", flavor.palette.light);
    elements.root.style.setProperty("--accent", flavor.palette.accent);
    elements.root.style.setProperty("--accent-soft", flavor.palette.accentSoft);
    flavor.palette.particleColors.forEach((color, index) => elements.root.style.setProperty(`--particle-${index}`, color));
  }

  function renderFlavor(index, announce = true) {
    const nextIndex = (index + flavors.length) % flavors.length;
    if (nextIndex === activeIndex && elements.name.textContent) return;
    activeIndex = nextIndex;
    const flavor = flavors[activeIndex];

    setPalette(flavor);
    elements.eyebrow.textContent = flavor.eyebrow;
    elements.name.textContent = flavor.shortName;
    elements.description.textContent = flavor.description;
    elements.detail.textContent = flavor.detail;
    elements.price.textContent = formatPrice(flavor.price);
    elements.purchaseName.textContent = flavor.shortName;
    elements.buy.href = `?checkout=1&flavor=${encodeURIComponent(flavor.id)}`;
    elements.buy.setAttribute("aria-label", `Comprar ${flavor.name} por ${formatPrice(flavor.price)}`);
    elements.currentIndex.textContent = String(activeIndex + 1).padStart(2, "0");

    [...elements.tabs.children].forEach((tab, tabIndex) => {
      const selected = tabIndex === activeIndex;
      tab.classList.toggle("active", selected);
      tab.setAttribute("aria-selected", String(selected));
      tab.tabIndex = selected ? 0 : -1;
    });

    if (!reducedMotion.matches) {
      elements.content.animate(
        [{ opacity: .18, filter: "blur(4px)" }, { opacity: 1, filter: "blur(0)" }],
        { duration: 560, easing: "cubic-bezier(.22,1,.36,1)" },
      );
    }
    if (announce) elements.announcement.textContent = `${flavor.name} selecionado.`;
  }

  function seekToFlavor(index) {
    const nextIndex = (index + flavors.length) % flavors.length;
    renderFlavor(nextIndex);
    const segmentCenter = (nextIndex + .5) / flavors.length;
    if (Number.isFinite(elements.video.duration)) {
      elements.video.currentTime = elements.video.duration * segmentCenter;
    }
    pendingSeekIndex = Number.isFinite(elements.video.duration) ? null : nextIndex;
  }

  function syncInterfaceWithPlayback() {
    if (!Number.isFinite(elements.video.duration) || elements.video.duration <= 0) return;
    const progress = elements.video.currentTime / elements.video.duration;
    elements.progress.style.transform = `scaleX(${Math.max(0, Math.min(1, progress))})`;
    renderFlavor(Math.min(flavors.length - 1, Math.floor(progress * flavors.length)), false);
    elements.videoStatus.textContent = "Em reprodução";
  }

  function createTabs() {
    const fragment = document.createDocumentFragment();
    flavors.forEach((flavor, index) => {
      const button = document.createElement("button");
      button.type = "button";
      button.className = "flavor-tab";
      button.setAttribute("role", "tab");
      button.innerHTML = `<span>0${index + 1}</span><strong>${flavor.shortName}</strong>`;
      button.setAttribute("aria-label", `Ver ${flavor.name}`);
      button.addEventListener("click", () => seekToFlavor(index));
      fragment.append(button);
    });
    elements.tabs.append(fragment);
  }

  function createParticles() {
    const positions = [[12,12,3],[82,17,2],[72,38,4],[18,58,2],[88,69,3],[61,84,2],[28,88,3]];
    const fragment = document.createDocumentFragment();
    positions.forEach(([left, top, size], index) => {
      const particle = document.createElement("i");
      particle.dataset.color = String(index % 3);
      particle.style.cssText = `left:${left}%;top:${top}%;width:${size}px;height:${size}px;animation-delay:${index * .28}s`;
      fragment.append(particle);
    });
    elements.particles.append(fragment);
  }

  elements.video.src = VIDEO_DATA;
  elements.video.addEventListener("loadedmetadata", () => {
    if (pendingSeekIndex !== null) seekToFlavor(pendingSeekIndex);
    syncInterfaceWithPlayback();
    if (!reducedMotion.matches) elements.video.play().catch(() => {});
  });
  elements.video.addEventListener("timeupdate", syncInterfaceWithPlayback);
  elements.video.addEventListener("pointerdown", (event) => {
    pointerStartX = event.clientX;
    pointerCurrentX = event.clientX;
    elements.video.setPointerCapture(event.pointerId);
  });
  elements.video.addEventListener("pointermove", (event) => {
    if (pointerStartX !== null) pointerCurrentX = event.clientX;
  });
  elements.video.addEventListener("pointerup", () => {
    if (pointerStartX === null) return;
    const offset = pointerCurrentX - pointerStartX;
    if (Math.abs(offset) > 45) seekToFlavor(activeIndex + (offset < 0 ? 1 : -1));
    pointerStartX = null;
    pointerCurrentX = null;
  });
  elements.video.addEventListener("pointercancel", () => {
    pointerStartX = null;
    pointerCurrentX = null;
  });
  window.addEventListener("keydown", (event) => {
    if (event.key === "ArrowRight") seekToFlavor(activeIndex + 1);
    if (event.key === "ArrowLeft") seekToFlavor(activeIndex - 1);
  });

  createTabs();
  createParticles();
  renderFlavor(0, false);
  if (reducedMotion.matches) elements.video.pause();
  else elements.video.play().catch(() => {});
}

function initializeCheckout() {
  const requestedId = params.get("flavor");
  const product = flavors.find((flavor) => flavor.id === requestedId) || flavors[0];
  let quantity = 1;

  document.body.dataset.view = "checkout";
  document.title = "Checkout — Monster Energy";
  document.querySelector('meta[name="description"]').content = "Resumo do pedido Monster Energy.";
  document.body.innerHTML = `
    <main class="checkout-view">
      <div class="checkout-shell">
        <header>
          <a href="./index.html" class="back">← Voltar</a>
          <span class="wordmark" role="img" aria-label="Monster Energy"><span class="checkout-logo" aria-hidden="true"></span></span>
          <span class="step">CHECKOUT / 01</span>
        </header>
        <section class="checkout-card" aria-labelledby="checkout-title">
          <div class="checkout-intro">
            <span class="eyebrow">Seu pedido</span>
            <h1 id="checkout-title">Energia<br />selecionada.</h1>
            <p>Revise o produto e a quantidade antes de continuar.</p>
          </div>
          <div class="order-summary">
            <span class="demo-label">Checkout demonstrativo</span>
            <div class="product-line">
              <div><span class="product-index">01</span><h2 id="product-name"></h2><p id="product-detail"></p></div>
              <strong id="unit-price"></strong>
            </div>
            <div class="quantity-row">
              <span>Quantidade</span>
              <div class="quantity-control">
                <button id="decrease" type="button" aria-label="Diminuir quantidade">−</button>
                <output id="quantity" aria-live="polite">1</output>
                <button id="increase" type="button" aria-label="Aumentar quantidade">+</button>
              </div>
            </div>
            <div class="total-row"><span>Total</span><strong id="total-price"></strong></div>
            <button class="continue-button" id="continue-button" type="button">Continuar para pagamento <span>→</span></button>
            <p class="checkout-status" id="checkout-status" aria-live="polite">Nenhuma cobrança será realizada nesta demonstração.</p>
          </div>
        </section>
      </div>
    </main>`;

  document.documentElement.style.setProperty("--accent", product.palette.accent);
  document.documentElement.style.setProperty("--accent-soft", product.palette.accentSoft);
  document.querySelector("#product-name").textContent = product.name;
  document.querySelector("#product-detail").textContent = product.detail;
  document.querySelector("#unit-price").textContent = formatPrice(product.price);
  document.querySelector(".product-index").textContent = String(flavors.indexOf(product) + 1).padStart(2, "0");

  const total = document.querySelector("#total-price");
  const quantityElement = document.querySelector("#quantity");
  const decrease = document.querySelector("#decrease");
  const increase = document.querySelector("#increase");
  const continueButton = document.querySelector("#continue-button");
  const status = document.querySelector("#checkout-status");

  const updateQuantity = () => {
    quantityElement.value = String(quantity);
    quantityElement.textContent = String(quantity);
    total.textContent = formatPrice(product.price * quantity);
    decrease.disabled = quantity === 1;
  };
  decrease.addEventListener("click", () => {
    quantity = Math.max(1, quantity - 1);
    updateQuantity();
  });
  increase.addEventListener("click", () => {
    quantity = Math.min(24, quantity + 1);
    updateQuantity();
  });
  continueButton.addEventListener("click", () => {
    status.textContent = "Checkout demonstrativo: conecte seu provedor de pagamento para concluir pedidos reais.";
    continueButton.textContent = "Pedido revisado ✓";
  });
  updateQuantity();
}
